"""Brute-force reference analyzer for tiny instances (validation only)."""
import sys, itertools
from fractions import Fraction
from math import lcm

sys.path.insert(0, '/workspace/submission')
import analyze as A


def loads_for(coms, E, qrow):
    loads = [Fraction(0)] * E
    for ci, (_cid, _src, _tgt, routes) in enumerate(coms):
        wsum = sum(w for _p, w in routes)
        for path, w in routes:
            amt = Fraction(qrow[ci] * w, wsum)
            for ei in path:
                loads[ei] += amt
    return loads


def ref_analyze(inst):
    edges = inst['edges']; coms = inst['commodities']; snaps = inst['snapshots']
    domains = inst['domains']; max_faults = inst['max_faults']
    S = len(snaps); C = len(coms); E = len(edges)
    nodes = inst['nodes']
    dom_idx = {d: i for i, d in enumerate(domains)}
    nd = len(domains)

    # per-snapshot feasible (vector, violset-bitmask)
    per = []
    for s in range(S):
        bnd = snaps[s][1]
        obs = snaps[s][4]
        ranges = [range(lo, hi + 1) for (lo, hi) in bnd]
        feas = {}
        if C == 0:
            combos = [()]
        else:
            combos = itertools.product(*ranges)
        for combo in combos:
            qrow = list(combo)
            loads = loads_for(coms, E, qrow)
            ing = {}
            egr = {}
            for ci, (_cid, src, tgt, _r) in enumerate(coms):
                ing[src] = ing.get(src, 0) + qrow[ci]
                egr[tgt] = egr.get(tgt, 0) + qrow[ci]
            ok = True
            mask = 0
            for (_oid, metric, target, lo, hi, dom) in obs:
                if metric == 'demand':
                    val = qrow[[c[0] for c in coms].index(target)]
                elif metric == 'link':
                    val = loads[[e[0] for e in edges].index(target)]
                elif metric == 'ingress':
                    val = ing.get(target, 0)
                else:
                    val = egr.get(target, 0)
                if not (lo <= val <= hi):
                    if dom is None:
                        ok = False
                        break
                    mask |= (1 << dom_idx[dom])
            if not ok:
                continue
            if any(loads[e] > edges[e][3] for e in range(E)):
                continue
            feas.setdefault(mask, []).append(qrow)
        per.append(feas)

    # DP over achievable unions
    reach = [None] * (S + 1)
    reach[S] = frozenset([0])
    for i in range(S - 1, -1, -1):
        nxt = set()
        for u in reach[i + 1]:
            for m in per[i]:
                nxt.add(u | m)
        reach[i] = frozenset(x for x in nxt if bin(x).count('1') <= max_faults)
    if not reach[0]:
        return {'id': None, 'status': 'infeasible'}
    k = min(bin(u).count('1') for u in reach[0])

    # enumerate F
    stats = {
        'dmin': [[None] * C for _ in range(S)],
        'dmax': [[None] * C for _ in range(S)],
        'lmin': [[None] * E for _ in range(S)],
        'lmax': [[None] * E for _ in range(S)],
        'any_agree': [False] * S,
        'all_agree': [True] * S,
        'any_fault': [False] * nd,
        'all_fault': [True] * nd,
        'first': None,
        'same': True,
        'count': 0,
        'members': [],
    }

    def dfs(i, union, chosen):
        if i == S:
            if union != 0 and bin(union).count('1') != k:
                return
            if bin(union).count('1') != k:
                return
            stats['count'] += 1
            qmat = list(chosen)
            for s in range(S):
                qrow = qmat[s]
                for c in range(C):
                    v = qrow[c]
                    if stats['dmin'][s][c] is None or v < stats['dmin'][s][c]:
                        stats['dmin'][s][c] = v
                    if stats['dmax'][s][c] is None or v > stats['dmax'][s][c]:
                        stats['dmax'][s][c] = v
                loads = loads_for(coms, E, qrow)
                for e in range(E):
                    if stats['lmin'][s][e] is None or loads[e] < stats['lmin'][s][e]:
                        stats['lmin'][s][e] = loads[e]
                    if stats['lmax'][s][e] is None or loads[e] > stats['lmax'][s][e]:
                        stats['lmax'][s][e] = loads[e]
                ctrl = snaps[s][2]; tol = snaps[s][3]
                agree = all(abs(qrow[c] - ctrl[c]) <= tol for c in range(C))
                if agree:
                    stats['any_agree'][s] = True
                else:
                    stats['all_agree'][s] = False
            for d in range(nd):
                if union & (1 << d):
                    stats['any_fault'][d] = True
                else:
                    stats['all_fault'][d] = False
            if stats['first'] is None:
                stats['first'] = [list(r) for r in qmat]
            elif stats['same']:
                if stats['first'] != qmat:
                    stats['same'] = False
            if len(stats['members']) < 2 or len(stats['members']) < 40:
                stats['members'].append(([list(r) for r in qmat], union))
            if len(stats['members']) > 60:
                stats['members'].pop()
            return
        for m, vecs in per[i].items():
            nu = union | m
            if bin(nu).count('1') > k:
                continue
            # prune: can remaining snapshots reach exactly k?
            ok = False
            for v in reach[i + 1]:
                uu = nu | v
                if bin(uu).count('1') == k:
                    ok = True
                    break
            if not ok:
                continue
            for vec in vecs:
                chosen.append(vec)
                dfs(i + 1, nu, chosen)
                chosen.pop()

    dfs(0, 0, [])

    out = {
        'status': 'unique' if stats['same'] else 'ambiguous',
        'min_faults': k,
        'faults': {
            'forced': [domains[d] for d in range(nd) if stats['all_fault'][d]],
            'possible': [domains[d] for d in range(nd) if stats['any_fault'][d]],
        },
        'snapshots': [],
    }
    for s in range(S):
        out['snapshots'].append({
            'id': snaps[s][0],
            'demands': [[stats['dmin'][s][c], stats['dmax'][s][c]] for c in range(C)],
            'links': [[_fmt(stats['lmin'][s][e]), _fmt(stats['lmax'][s][e])] for e in range(E)],
            'verdict': ('consistent' if stats['all_agree'][s]
                        else ('inconsistent' if not stats['any_agree'][s] else 'undetermined')),
        })
    return out, stats


def _fmt(fr):
    return '%d/%d' % (fr.numerator, fr.denominator)


if __name__ == '__main__':
    import json
    for line in sys.stdin:
        req = json.loads(line)
        if 'version' not in req:
            print(json.dumps({'id': None, 'status': 'error', 'error': 'invalid_instance'}))
            continue
        rid = req.get('id')
        try:
            inst = A._parse_request(req)
            res, stats = ref_analyze(inst)
            res['id'] = rid
        except Exception as e:
            import traceback; traceback.print_exc()
            res = {'id': rid, 'status': 'error', 'error': 'invalid_instance'}
        print(json.dumps(res))
